import React, { useEffect, useState } from 'react';
import ContentList from '../components/ContentList';
import ContentForm from '../components/ContentForm';
import { loadThreads } from '../utils/data';

const ContentPage = ({ match }) => {
  const [threads, setThreads] = useState(loadThreads());
  const [activeThreadId, setActiveThreadId] = useState(threads[0]?.id);

  useEffect(() => { setThreads(loadThreads()); }, []);

  useEffect(() => { if (!activeThreadId && threads[0]) setActiveThreadId(threads[0].id); }, [threads, activeThreadId]);

  const thread = threads.find(t => t.id === activeThreadId) || threads[0] || { title: 'Sin publicaciones', posts: [] };

  const handleCreate = () => {
    const fresh = loadThreads();
    setThreads(fresh);
  };

  return (
    <main className="container">
      <div className="row">
        <div className="col">
          <h2 className="neon">Publicaciones</h2>
          <ContentList onSelect={(id) => setActiveThreadId(id)} selectedId={activeThreadId} filter={''} />
        </div>
        <div className="col">
          <div className="card">
            <h3>{thread.title}</h3>
            <div>
              {thread.posts.map(p => (
                <article key={p.id} className="card" style={{ marginBottom: '0.5rem' }}>
                  <div style={{ fontSize: '0.85rem', color: '#9bd6b1' }}>{p.author}</div>
                  <p style={{ marginTop: '0.25rem' }}>{p.body}</p>
                </article>
              ))}
            </div>

            <h4>Comentar</h4>
            <ContentForm threadId={thread.id} onCreate={handleCreate} />
          </div>
        </div>
      </div>
    </main>
  );
};

export default ContentPage;
